<script setup lang="ts">
import { computed } from 'vue'
import { SPINNER_ART } from '../../themes/spinnerArt'
import type { SpinnerVariant } from '../../utils/spinner'

// Every spinner is one SVG of themes/spinnerArt.ts (generated by scripts/build_spinner_sets.py): the festival five (ring, alpona, lotus, chakra, dhak: the design system's own
// motifs, drawn here in code until W18) and the 45 of the design project "Spinner Sets" (five occasions of nine). Per the design's rule, "one motif per surface": a call site picks
// one variant and keeps it; which one comes from the square's kept set (utils/spinner.ts randomSpinnerVariant). Colours and size are set by the CSS of styles/spinner-sets.css
// (.rs-spinner-art): the main colour is the theme's accent, the second and third are derived from it as in the design; `on-dark` and `muted` are the design's dark tone and a grey.
// Sizes: sm 16, md 24, lg 40, xl 56 (the design system's) and xxl 96 (the largest of the Spinner Sets design: 24, 40, 56, 96).
const props = withDefaults(
  defineProps<{
    variant?: SpinnerVariant
    size?: 'sm' | 'md' | 'lg' | 'xl' | 'xxl'
    tone?: 'primary' | 'on-dark' | 'muted'
    label?: string
  }>(),
  { variant: 'ring', size: 'md', tone: 'primary', label: 'Loading' },
)

const SIZES: Record<string, number> = { sm: 16, md: 24, lg: 40, xl: 56, xxl: 96 }
const px = computed(() => SIZES[props.size] ?? SIZES.md)
// an unknown variant draws the ring, the first of the festival five
const art = computed(() => SPINNER_ART.find((a) => a.id === props.variant) ?? SPINNER_ART[0])
const toneClass = computed(() => (props.tone === 'on-dark' ? 'rs-spinner-art--dark' : props.tone === 'muted' ? 'rs-spinner-art--muted' : ''))
</script>

<template>
  <span role="status" :aria-label="label" style="display: inline-flex">
    <span aria-hidden="true" class="rs-spinner-art" :class="toneClass" :style="{ '--sz': px + 'px' }" v-html="art.svg" />
  </span>
</template>
